import assert from 'node:assert/strict';
import fs from 'node:fs';
import {spawn} from 'node:child_process';
import {read,json,sha} from './source-only-backup-20261019.mjs';
const root='F:/VisibleMedicine/staging/20261022-reviewed-regression-runtime-linking';
const suffix=process.argv[2]??'';assert(['','-v2','-v3'].includes(suffix));
const receiptPath=root+'/PRODUCT_SOURCE'+suffix.toUpperCase().replace('-','_')+'.json',receiptBytes=read(receiptPath),receipt=JSON.parse(receiptBytes),website=receipt.website;
const evidence=root+'/native-mri-runtime'+suffix;assert(!fs.existsSync(evidence));
for(const row of receipt.sourceRows)assert.equal(sha(read(website+'/'+row.path)),row.sha256,'Preflight source: '+row.path);
const tests=fs.readdirSync(website+'/tests').filter(name=>/^(?:regional-mri-|regional-reference-).+\.test\.ts$/.test(name)).map(name=>'tests/'+name).sort();
if(suffix==='-v3')tests.push('tests/regional-link-role-preservation-20261021.test.mjs','tests/review-navigation-six-harness-preservation.test.mjs','tests/clinical-review-thoracic-eus.test.ts');
assert(tests.length>=50&&tests.length<65);
const args=['--test','--experimental-strip-types','--test-concurrency=1','--test-reporter=tap',...tests];
fs.mkdirSync(evidence);
const inputs=tests.map(path=>({path,sha256:sha(read(website+'/'+path))}));
fs.writeFileSync(evidence+'/INPUTS.json',JSON.stringify({at:new Date().toISOString(),website,receiptPath,receiptSha256:sha(receiptBytes),inputs,args},null,2)+'\n',{flag:'wx'});
const output=fs.createWriteStream(evidence+'/child.tap',{flags:'wx'}),errors=fs.createWriteStream(evidence+'/child.stderr',{flags:'wx'});
const child=spawn(process.execPath,args,{cwd:website,env:{...process.env,GOMAXPROCS:'2',RAYON_NUM_THREADS:'1'},windowsHide:true,stdio:['ignore','pipe','pipe']});
child.stdout.pipe(output);child.stderr.pipe(errors);
console.log(JSON.stringify({phase:'running',pid:child.pid,tests:tests.length,evidence,ownerPreviewChanged:false}));
const result=await new Promise((resolve,reject)=>{child.once('error',reject);child.once('close',(code,signal)=>resolve({code,signal}));});
await Promise.all([output,errors].map(stream=>new Promise(resolve=>stream.closed?resolve():stream.once('close',resolve))));
const tap=read(evidence+'/child.tap').toString('utf8'),counts={};
for(const key of ['tests','pass','fail','cancelled','skipped','todo'])counts[key]=Number(tap.match(new RegExp('^# '+key+' (\\d+)\\r?$','m'))?.[1]??NaN);
const drift=receipt.sourceRows.filter(row=>sha(read(website+'/'+row.path))!==row.sha256).map(row=>row.path);
const terminal={at:new Date().toISOString(),terminal:true,...result,counts,sourceDrift:drift,sourceReceiptSha256:sha(read(receiptPath)),entryFiles:tests.length,
 tapSha256:sha(read(evidence+'/child.tap')),stderrSha256:sha(read(evidence+'/child.stderr')),ownerPreviewChanged:false,clinicalApproval:false,patientRegistration:false};
fs.writeFileSync(evidence+'/TERMINAL.json',JSON.stringify(terminal,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify(terminal));
process.exitCode=result.code===0&&counts.fail===0&&counts.skipped===0&&drift.length===0?0:1;
